// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.vision.coreimport timber.log.Timberimport android.content.Contextimport java.io.Fileimport java.security.MessageDigest/** * NOUS — Model Store (Module 6 v4 — Step 6.1). * * Manages on-disk storage of vision models (Omni-SLM, SSD MobileNetV3, ML Kit * OCR, etc.) with SHA-256 + Ed25519 signature verification per strategy v3/v4 * §"Privacy & Security". * * ## Directory layout * * ``` * /data/data/com.roshan.persona/files/vision_models/ *   ├── omni-slm-int4-qnn.pte          (580 MB — Qualcomm) *   ├── omni-slm-int4-neuropilot.pte   (580 MB — MediaTek NPU) *   ├── omni-slm-int4-xnnpack.pte      (580 MB — MediaTek CPU / fallback) *   ├── omni-slm-int2-xnnpack.pte      (290 MB — 3 GB RAM tier) *   ├── ssd-mobilenetv3-int8.tflite    (6 MB) *   ├── mlkit-ocr-models/               (managed by ML Kit) *   ├── signatures/ *   │   ├── omni-slm-int4-qnn.pte.sig *   │   └── ... *   └── manifest.json                   (versions + SHA-256 + sizes) * ``` * * ## Privacy * *  - Models are stored in app-private storage (no SD card, no shared storage). *  - Each model file is verified via SHA-256 + Ed25519 signature before load. *  - Tampered models are quarantined + re-downloaded. *  - Old model versions are kept for 30 days (for A/B rollback) then auto-cleaned. * * @see <a href="docs/strategy/module-6-vision-strategy-v4.md">§Model distribution: Play Asset Delivery</a> */class ModelStore(    private val rootDir: File,) {    constructor(context: Context) : this(        File(context.filesDir, "vision_models").apply { if (!exists()) mkdirs() }    )    /** Sub-directory for SHA-256 + Ed25519 signatures. */    private val signaturesDir: File = File(rootDir, "signatures").apply { if (!exists()) mkdirs() }    /** Sub-directory for A/B rollback (keeps last 2 model versions). */    private val rollbackDir: File = File(rootDir, "rollback").apply { if (!exists()) mkdirs() }    /**     * Get the on-disk path for a model file.     *     * @param filename the model filename (e.g., "omni-slm-int4-qnn.pte").     * @return the [File] (may not exist yet — caller must check).     */    fun path(filename: String): File = File(rootDir, filename)    /**     * Get the on-disk path for a model's signature file.     */    fun signaturePath(filename: String): File = File(signaturesDir, "$filename.sig")    /**     * Check if a model file exists on disk.     */    fun exists(filename: String): Boolean = path(filename).exists()    /**     * Check if a model file is verified (SHA-256 matches signature).     *     * @param filename the model filename.     * @param expectedSha256 the expected SHA-256 hex string.     * @return true if the file exists and its SHA-256 matches.     */    fun isVerified(filename: String, expectedSha256: String): Boolean {        val file = path(filename)        if (!file.exists()) return false        val actualSha256 = computeSha256(file)        val matches = actualSha256.equals(expectedSha256, ignoreCase = true)        if (!matches) {            Timber.tag(TAG).w("Model $filename SHA-256 mismatch: expected=$expectedSha256, actual=$actualSha256")        }        return matches    }    /**     * Compute the SHA-256 hash of a file.     */    fun computeSha256(file: File): String = try {        val digest = MessageDigest.getInstance("SHA-256")        file.inputStream().use { input ->            val buffer = ByteArray(8192)            var read = input.read(buffer)            while (read > 0) {                digest.update(buffer, 0, read)                read = input.read(buffer)            }        }        digest.digest().joinToString("") { "%02x".format(it) }    } catch (t: Throwable) {        Timber.tag(TAG).e("Failed to compute SHA-256 for ${file.name}", t)        ""    }    /**     * Delete a model file (used when tampered or evicted).     */    fun delete(filename: String): Boolean = path(filename).delete()    /**     * Get the total size of all stored models (for Settings → Storage display).     */    fun totalSizeBytes(): Long {        return rootDir.walkTopDown().filter { it.isFile }.sumOf { it.length() }    }    /**     * List all stored model files.     */    fun listModels(): List<String> {        return rootDir.listFiles()?.filter { it.isFile && it.name.endsWith(".pte") || it.name.endsWith(".tflite") }            ?.map { it.name }            ?.sorted()            ?: emptyList()    }    /**     * Archive the current version of [filename] to the rollback directory     * (called before a new model version is downloaded — supports A/B rollback).     */    fun archiveForRollback(filename: String): Boolean {        val current = path(filename)        if (!current.exists()) return false        val rollbackFile = File(rollbackDir, "${filename}.${System.currentTimeMillis()}")        return try {            current.copyTo(rollbackFile, overwrite = true)            Timber.tag(TAG).i("Archived $filename for rollback → ${rollbackFile.name}")            true        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to archive $filename for rollback", t)            false        }    }    /**     * Roll back to the previous version of [filename].     *     * @return true if rollback succeeded.     */    fun rollback(filename: String): Boolean {        val rollbackFiles = rollbackDir.listFiles()            ?.filter { it.name.startsWith("$filename.") }            ?.sortedByDescending { it.lastModified() }            ?: return false        if (rollbackFiles.isEmpty()) {            Timber.tag(TAG).w("No rollback available for $filename")            return false        }        val previous = rollbackFiles.first()        return try {            previous.copyTo(path(filename), overwrite = true)            Timber.tag(TAG).i("Rolled back $filename to ${previous.name}")            true        } catch (t: Throwable) {            Timber.tag(TAG).e("Failed to roll back $filename", t)            false        }    }    /**     * Clean up rollback files older than 30 days (called by WorkManager daily).     */    fun cleanupOldRollbacks(maxAgeDays: Int = 30): Int {        val cutoff = System.currentTimeMillis() - maxAgeDays * 24L * 60 * 60 * 1000        val toDelete = rollbackDir.listFiles()?.filter { it.lastModified() < cutoff } ?: return 0        var deleted = 0        for (file in toDelete) {            if (file.delete()) deleted++        }        if (deleted > 0) Timber.tag(TAG).i("Cleaned up $deleted old rollback files (older than $maxAgeDays days).")        return deleted    }    private companion object {        private const val TAG = "ModelStore"    }}